import { AutoProcessor, CLIPVisionModelWithProjection, RawImage, env } from '@xenova/transformers';

// Configure transformers.js for CRA compatibility (admin runs at /admin/)
env.allowLocalModels = false;
env.allowRemoteModels = true;
env.useBrowserCache = false;
env.useFSCache = false;
if (env.backends?.onnx?.wasm) {
  env.backends.onnx.wasm.wasmPaths = '/admin/';
}

// ── Singleton CLIP vision model + processor ──────────────────────────────────
let modelPromise = null;

function initCLIP() {
  if (!modelPromise) {
    console.log('[CLIP] Loading vision model + processor...');
    modelPromise = Promise.all([
      CLIPVisionModelWithProjection.from_pretrained('Xenova/clip-vit-base-patch32'),
      AutoProcessor.from_pretrained('Xenova/clip-vit-base-patch32'),
    ]).then(([model, processor]) => {
      console.log('[CLIP] Model ready');
      return { model, processor };
    }).catch(err => {
      console.error('[CLIP] Model load failed:', err);
      modelPromise = null;
      throw err;
    });
  }
  return modelPromise;
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function normalize(vec) {
  const norm = Math.sqrt(vec.reduce((sum, v) => sum + v * v, 0));
  if (norm === 0) return vec;
  return vec.map(v => v / norm);
}

// Fetch+blob to bypass CORS issues with Firebase Storage URLs.
async function loadImage(url) {
  return new Promise(async (resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error(`Failed to load: ${url.substring(0, 80)}`));

    if (url.startsWith('data:') || url.startsWith('blob:')) {
      img.src = url;
    } else {
      try {
        const res = await fetch(url);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const blob = await res.blob();
        img.src = URL.createObjectURL(blob);
      } catch (err) {
        reject(new Error(`Fetch failed for ${url.substring(0, 80)}: ${err.message}`));
      }
    }
  });
}

// 224×224 processing canvas (singleton).
let processingCanvas = null;
function getProcessingCtx() {
  if (!processingCanvas) {
    processingCanvas = document.createElement('canvas');
    processingCanvas.width = 224;
    processingCanvas.height = 224;
  }
  return processingCanvas.getContext('2d', { willReadFrequently: true });
}

// ── WebGL perspective warp (singleton) ───────────────────────────────────────
// Renders trapezoidal warps simulating off-axis viewing (yaw/pitch ~20°) so
// reference embeddings include angled views — Canvas-2D affine warps would
// miss the foreshortening that a phone camera captures from off-axis.
let glCanvas = null;
let glCtx = null;
let glProgram = null;
let glPosBuf = null;
let glTexBuf = null;
let glTexture = null;

const WARP_VS = `
  attribute vec3 aPosQ;
  attribute vec2 aTex;
  varying vec2 vTex;
  void main() {
    gl_Position = vec4(aPosQ.x * aPosQ.z, aPosQ.y * aPosQ.z, 0.0, aPosQ.z);
    vTex = aTex;
  }
`;

const WARP_FS = `
  precision mediump float;
  uniform sampler2D uTex;
  varying vec2 vTex;
  void main() { gl_FragColor = texture2D(uTex, vTex); }
`;

function initWarpGL() {
  if (glCanvas) return;
  glCanvas = document.createElement('canvas');
  glCanvas.width = 224;
  glCanvas.height = 224;
  const gl = glCanvas.getContext('webgl', { premultipliedAlpha: false });
  if (!gl) throw new Error('WebGL unavailable');

  const compile = (type, src) => {
    const s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) {
      throw new Error(gl.getShaderInfoLog(s));
    }
    return s;
  };
  glProgram = gl.createProgram();
  gl.attachShader(glProgram, compile(gl.VERTEX_SHADER, WARP_VS));
  gl.attachShader(glProgram, compile(gl.FRAGMENT_SHADER, WARP_FS));
  gl.linkProgram(glProgram);
  if (!gl.getProgramParameter(glProgram, gl.LINK_STATUS)) {
    throw new Error(gl.getProgramInfoLog(glProgram));
  }

  glPosBuf = gl.createBuffer();
  glTexBuf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, glTexBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([0,1, 1,1, 0,0, 1,0]), gl.STATIC_DRAW);

  glTexture = gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, glTexture);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  glCtx = gl;
}

// q > 1 = near edge (enlarged), q < 1 = far edge (foreshortened).
// SHRINK collapses the far edge inward so the warped artwork sits as a
// trapezoid inside the canvas with black bars — matching how a phone sees
// an off-axis painting.
const Q_NEAR = 1.09, Q_FAR = 0.91, SHRINK = 0.85;
const WARP_PARAMS = {
  yawLeft:  { TL: [-1,  1,       Q_NEAR], TR: [ 1,  SHRINK,  Q_FAR ],
              BL: [-1, -1,       Q_NEAR], BR: [ 1, -SHRINK,  Q_FAR ] },
  yawRight: { TL: [-1,  SHRINK,  Q_FAR ], TR: [ 1,  1,       Q_NEAR],
              BL: [-1, -SHRINK,  Q_FAR ], BR: [ 1, -1,       Q_NEAR] },
  pitchUp:  { TL: [-SHRINK,  1,  Q_FAR ], TR: [ SHRINK,  1,  Q_FAR ],
              BL: [-1,      -1,  Q_NEAR], BR: [ 1,      -1,  Q_NEAR] },
  pitchDown:{ TL: [-1,       1,  Q_NEAR], TR: [ 1,       1,  Q_NEAR],
              BL: [-SHRINK, -1,  Q_FAR ], BR: [ SHRINK, -1,  Q_FAR ] },
};

function renderWarp(img, params) {
  const gl = glCtx;
  gl.viewport(0, 0, 224, 224);
  gl.clearColor(0, 0, 0, 1);
  gl.clear(gl.COLOR_BUFFER_BIT);

  gl.bindTexture(gl.TEXTURE_2D, glTexture);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, img);

  gl.useProgram(glProgram);
  gl.bindBuffer(gl.ARRAY_BUFFER, glPosBuf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([
    ...params.TL, ...params.TR, ...params.BL, ...params.BR,
  ]), gl.DYNAMIC_DRAW);
  const aPosQ = gl.getAttribLocation(glProgram, 'aPosQ');
  gl.enableVertexAttribArray(aPosQ);
  gl.vertexAttribPointer(aPosQ, 3, gl.FLOAT, false, 0, 0);

  gl.bindBuffer(gl.ARRAY_BUFFER, glTexBuf);
  const aTex = gl.getAttribLocation(glProgram, 'aTex');
  gl.enableVertexAttribArray(aTex);
  gl.vertexAttribPointer(aTex, 2, gl.FLOAT, false, 0, 0);

  gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
}

// ── Variant generation ───────────────────────────────────────────────────────
// 8 Canvas-2D variants (always) + 4 WebGL perspective warps (best effort).
// Ported from gestalt/src/services/clipService.js getAugmentedEmbeddingsFromUrl.
async function getAugmentedEmbeddingsFromImage(img, model, processor, onVariant) {
  const ctx = getProcessingCtx();
  const w = img.naturalWidth;
  const h = img.naturalHeight;
  if (!w || !h) throw new Error('Source image has zero dimensions');

  async function runClip() {
    const imageData = ctx.getImageData(0, 0, 224, 224);
    const rawImage = new RawImage(imageData.data, 224, 224, 4);
    const imageInputs = await processor(rawImage);
    const { image_embeds } = await model(imageInputs);
    return normalize(Array.from(image_embeds.data));
  }

  const variants = [];
  let n = 0;
  const TOTAL = 12;

  // 1. Original
  onVariant?.(++n, TOTAL, 'original');
  ctx.filter = 'none';
  ctx.clearRect(0, 0, 224, 224);
  ctx.drawImage(img, 0, 0, w, h, 0, 0, 224, 224);
  variants.push(await runClip());

  // 2-3. Rotation ±8° — overdraw so rotated corners cover full 224×224
  for (const angleDeg of [8, -8]) {
    onVariant?.(++n, TOTAL, `rotate ${angleDeg}°`);
    const rad = angleDeg * Math.PI / 180;
    const overdraw = Math.cos(Math.abs(rad)) + Math.sin(Math.abs(rad));
    const size = 224 * overdraw;
    ctx.filter = 'none';
    ctx.clearRect(0, 0, 224, 224);
    ctx.save();
    ctx.translate(112, 112);
    ctx.rotate(rad);
    ctx.drawImage(img, 0, 0, w, h, -size / 2, -size / 2, size, size);
    ctx.restore();
    variants.push(await runClip());
  }

  // 4-5. Brightness ±25%
  for (const factor of [1.25, 0.75]) {
    onVariant?.(++n, TOTAL, `brightness ${factor}`);
    ctx.filter = `brightness(${factor})`;
    ctx.clearRect(0, 0, 224, 224);
    ctx.drawImage(img, 0, 0, w, h, 0, 0, 224, 224);
    variants.push(await runClip());
  }
  ctx.filter = 'none';

  // 6-7. Center crops 85% / 70% — simulate user closer than reference photo
  for (const cropFactor of [0.85, 0.70]) {
    onVariant?.(++n, TOTAL, `crop ${cropFactor}`);
    const margin = (1 - cropFactor) / 2;
    ctx.clearRect(0, 0, 224, 224);
    ctx.drawImage(img, w * margin, h * margin, w * cropFactor, h * cropFactor, 0, 0, 224, 224);
    variants.push(await runClip());
  }

  // 8. Top-shifted crop (drops bottom 20%) — common framing miss
  onVariant?.(++n, TOTAL, 'top crop');
  ctx.clearRect(0, 0, 224, 224);
  ctx.drawImage(img, 0, 0, w, h * 0.8, 0, 0, 224, 224);
  variants.push(await runClip());

  // 9-12. Perspective warps (yaw/pitch ~20°) — best-effort. WebGL failure
  // on any device leaves the original 8 variants intact.
  try {
    initWarpGL();
    for (const name of ['yawLeft', 'yawRight', 'pitchUp', 'pitchDown']) {
      onVariant?.(++n, TOTAL, name);
      renderWarp(img, WARP_PARAMS[name]);
      ctx.filter = 'none';
      ctx.clearRect(0, 0, 224, 224);
      ctx.drawImage(glCanvas, 0, 0);
      variants.push(await runClip());
    }
  } catch (err) {
    console.warn('[Embeddings] Perspective warp skipped:', err?.message ?? err);
  }

  return variants;
}

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Generate CLIP embeddings for all images of an artwork.
 * Mirrors the gestalt AR app's getAugmentedEmbeddingsFromUrl pipeline:
 * 8 Canvas-2D variants (rotation, brightness, crops, top-shift) + 4 WebGL
 * perspective warps (yaw/pitch ~20°) — up to 12 embeddings per source image.
 *
 * @param {string[]} imageUrls
 * @param {(progress: string) => void} onProgress
 * @returns {Promise<Array<{ v: number[] }>>}
 */
export async function generateEmbeddings(imageUrls, onProgress) {
  const { model, processor } = await initCLIP();

  onProgress?.('CLIP model ready — processing images...');
  const allEmbeddings = [];

  for (let i = 0; i < imageUrls.length; i++) {
    const url = imageUrls[i];
    console.log(`[CLIP] Loading image ${i + 1}/${imageUrls.length}: ${url.substring(0, 80)}...`);
    onProgress?.(`Loading image ${i + 1}/${imageUrls.length}...`);

    let img;
    try {
      img = await loadImage(url);
    } catch (err) {
      console.warn(`[CLIP] Skipping image ${i + 1}: ${err.message}`);
      continue;
    }

    const reportVariant = (n, total, label) => {
      onProgress?.(`Image ${i + 1}/${imageUrls.length} — variant ${n}/${total} (${label})`);
    };

    try {
      const vectors = await getAugmentedEmbeddingsFromImage(img, model, processor, reportVariant);
      for (const v of vectors) allEmbeddings.push({ v });
    } catch (err) {
      console.warn(`[CLIP] Augmentation failed for image ${i + 1}: ${err.message}`);
    }
  }

  onProgress?.(`Done — ${allEmbeddings.length} embeddings generated`);
  return allEmbeddings;
}
